-- =====================================================================
--  TOYLAND v2 - He thong quan ly cua hang do choi truc tuyen
--  CSDL: MySQL 8.x hoac MariaDB 10.4+ (XAMPP)
--  Chay TOAN BO file nay trong MySQL Workbench / phpMyAdmin (tab SQL).
--  Script se XOA va TAO LAI CSDL toyland_v2.
--
--  Tai khoan mau:
--     admin     / admin123   (ADMIN  - toan quyen)
--     staff     / staff123   (STAFF  - xu ly don, kho, san pham, danh gia)
--     khachhang / 123456     (CUSTOMER) + 7 khach hang khac, mat khau 123456
-- =====================================================================

DROP DATABASE IF EXISTS toyland_v2;
CREATE DATABASE toyland_v2 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE toyland_v2;
SET NAMES utf8mb4;
-- MySQL Workbench bat "Safe Updates" mac dinh -> tat tam thoi de cac lenh UPDATE du lieu mau chay duoc
SET SQL_SAFE_UPDATES = 0;

-- =====================================================================
-- 1. NGUOI DUNG & XAC THUC
-- =====================================================================
CREATE TABLE users (
    id                     BIGINT       NOT NULL AUTO_INCREMENT PRIMARY KEY,
    username               VARCHAR(50)  NOT NULL UNIQUE,
    password               VARCHAR(100) NOT NULL,
    full_name              VARCHAR(100) NOT NULL,
    email                  VARCHAR(100) NOT NULL UNIQUE,
    phone                  VARCHAR(20),
    role                   VARCHAR(20)  NOT NULL DEFAULT 'CUSTOMER',
    enabled                BOOLEAN      NOT NULL DEFAULT TRUE,
    failed_login_attempts  INT          NOT NULL DEFAULT 0,
    locked_until           DATETIME     NULL,
    consent_at             DATETIME     NULL,
    -- Xac nhan email (giong email_verified_at cua Laravel): NULL = chua xac nhan
    email_verified_at      DATETIME     NULL,
    deleted                BOOLEAN      NOT NULL DEFAULT FALSE,
    -- Khach hang than thiet: diem hien co + tong diem tich luy tu truoc den nay (xep hang thanh vien)
    points                 INT          NOT NULL DEFAULT 0,
    lifetime_points        INT          NOT NULL DEFAULT 0,
    created_at             DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at             DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_users_points CHECK (points >= 0),
    CONSTRAINT chk_users_role CHECK (role IN ('ADMIN','STAFF','CUSTOMER'))
) ENGINE=InnoDB;

CREATE TABLE refresh_tokens (
    id          BIGINT       NOT NULL AUTO_INCREMENT PRIMARY KEY,
    user_id     BIGINT       NOT NULL,
    token       VARCHAR(100) NOT NULL UNIQUE,
    expires_at  DATETIME     NOT NULL,
    revoked     BOOLEAN      NOT NULL DEFAULT FALSE,
    created_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_rt_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE password_reset_tokens (
    id          BIGINT       NOT NULL AUTO_INCREMENT PRIMARY KEY,
    user_id     BIGINT       NOT NULL,
    token       VARCHAR(100) NOT NULL UNIQUE,
    expires_at  DATETIME     NOT NULL,
    used        BOOLEAN      NOT NULL DEFAULT FALSE,
    created_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_prt_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- Link xac nhan email: chi luu SHA-256 cua token (lo CSDL cung khong dung duoc link),
-- ghi kem email can xac nhan -> doi email sau khi gui link thi link cu tu vo hieu.
CREATE TABLE email_verification_tokens (
    id          BIGINT       NOT NULL AUTO_INCREMENT PRIMARY KEY,
    user_id     BIGINT       NOT NULL,
    email       VARCHAR(100) NOT NULL,
    token_hash  CHAR(64)     NOT NULL UNIQUE,
    expires_at  DATETIME     NOT NULL,
    used_at     DATETIME     NULL,
    created_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_evt_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    INDEX idx_evt_user (user_id, created_at)
) ENGINE=InnoDB;

-- So dia chi: dung ma dia gioi cua GHN (ProvinceID / DistrictID / WardCode) de tinh phi ship
CREATE TABLE addresses (
    id             BIGINT       NOT NULL AUTO_INCREMENT PRIMARY KEY,
    user_id        BIGINT       NOT NULL,
    receiver_name  VARCHAR(100) NOT NULL,
    phone          VARCHAR(20)  NOT NULL,
    province_id    INT,
    province_name  VARCHAR(100) NOT NULL,
    district_id    INT,
    district_name  VARCHAR(100) NOT NULL,
    ward_code      VARCHAR(20),
    ward_name      VARCHAR(100) NOT NULL,
    detail         VARCHAR(255) NOT NULL,
    is_default     BOOLEAN      NOT NULL DEFAULT FALSE,
    created_at     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_addr_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- =====================================================================
-- 2. DANH MUC SAN PHAM
-- =====================================================================
CREATE TABLE categories (
    id           BIGINT       NOT NULL AUTO_INCREMENT PRIMARY KEY,
    parent_id    BIGINT       NULL,
    name         VARCHAR(100) NOT NULL,
    slug         VARCHAR(120) NOT NULL UNIQUE,
    description  VARCHAR(500),
    image_url    VARCHAR(500),
    icon         VARCHAR(50),
    sort_order   INT          NOT NULL DEFAULT 0,
    active       BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_cat_parent FOREIGN KEY (parent_id) REFERENCES categories(id)
) ENGINE=InnoDB;

CREATE TABLE brands (
    id           BIGINT       NOT NULL AUTO_INCREMENT PRIMARY KEY,
    name         VARCHAR(100) NOT NULL UNIQUE,
    slug         VARCHAR(120) NOT NULL UNIQUE,
    logo_url     VARCHAR(500),
    country      VARCHAR(100),
    description  VARCHAR(500),
    created_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

-- Nhan vat / chu de (Marvel, Paw Patrol, Harry Potter...)
CREATE TABLE franchises (
    id           BIGINT       NOT NULL AUTO_INCREMENT PRIMARY KEY,
    name         VARCHAR(100) NOT NULL UNIQUE,
    slug         VARCHAR(120) NOT NULL UNIQUE,
    image_url    VARCHAR(500),
    description  VARCHAR(500),
    created_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

-- =====================================================================
-- 3. SAN PHAM - BIEN THE (mo hinh Shopify: toi da 2 thuoc tinh option1/option2)
-- =====================================================================
CREATE TABLE products (
    id                   BIGINT        NOT NULL AUTO_INCREMENT PRIMARY KEY,
    name                 VARCHAR(200)  NOT NULL,
    slug                 VARCHAR(220)  NOT NULL UNIQUE,
    short_description    VARCHAR(500),
    description          TEXT,
    category_id          BIGINT        NOT NULL,
    brand_id             BIGINT        NULL,
    -- Thong tin dac thu do choi (QCVN 3:2019/BKHCN)
    age_min_months       INT           NOT NULL DEFAULT 0,
    age_max_months       INT           NULL,
    gender               VARCHAR(10)   NOT NULL DEFAULT 'UNISEX',
    material             VARCHAR(100),
    brand_origin         VARCHAR(100),
    made_in              VARCHAR(100),
    manufacture_year     INT,
    battery              VARCHAR(100),
    small_parts_warning  BOOLEAN       NOT NULL DEFAULT FALSE,
    safety_warning       VARCHAR(500),
    cr_certified         BOOLEAN       NOT NULL DEFAULT TRUE,
    importer             VARCHAR(255),
    length_cm            INT           NOT NULL DEFAULT 20,
    width_cm             INT           NOT NULL DEFAULT 15,
    height_cm            INT           NOT NULL DEFAULT 10,
    video_url            VARCHAR(500),
    -- Ten thuoc tinh bien the (null = khong co)
    option1_name         VARCHAR(50),
    option2_name         VARCHAR(50),
    status               VARCHAR(20)   NOT NULL DEFAULT 'ACTIVE',
    featured             BOOLEAN       NOT NULL DEFAULT FALSE,
    online_exclusive     BOOLEAN       NOT NULL DEFAULT FALSE,
    -- Cot tong hop (denormalized) de loc/sap xep nhanh
    min_price            DECIMAL(15,2) NOT NULL DEFAULT 0,
    max_price            DECIMAL(15,2) NOT NULL DEFAULT 0,
    total_stock          INT           NOT NULL DEFAULT 0,
    sold_count           INT           NOT NULL DEFAULT 0,
    avg_rating           DECIMAL(3,2)  NOT NULL DEFAULT 0,
    review_count         INT           NOT NULL DEFAULT 0,
    search_text          VARCHAR(1000),
    meta_title           VARCHAR(200),
    meta_description     VARCHAR(500),
    deleted              BOOLEAN       NOT NULL DEFAULT FALSE,
    created_at           DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at           DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_prod_category FOREIGN KEY (category_id) REFERENCES categories(id),
    CONSTRAINT fk_prod_brand    FOREIGN KEY (brand_id)    REFERENCES brands(id),
    CONSTRAINT chk_prod_gender  CHECK (gender IN ('BOY','GIRL','UNISEX')),
    CONSTRAINT chk_prod_status  CHECK (status IN ('DRAFT','ACTIVE','INACTIVE','COMING_SOON'))
) ENGINE=InnoDB;

CREATE INDEX idx_prod_status   ON products(status, deleted);
CREATE INDEX idx_prod_minprice ON products(min_price);

CREATE TABLE product_franchises (
    product_id    BIGINT NOT NULL,
    franchise_id  BIGINT NOT NULL,
    PRIMARY KEY (product_id, franchise_id),
    CONSTRAINT fk_pf_product   FOREIGN KEY (product_id)   REFERENCES products(id)   ON DELETE CASCADE,
    CONSTRAINT fk_pf_franchise FOREIGN KEY (franchise_id) REFERENCES franchises(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE product_variants (
    id                BIGINT        NOT NULL AUTO_INCREMENT PRIMARY KEY,
    product_id        BIGINT        NOT NULL,
    sku               VARCHAR(60)   NOT NULL UNIQUE,
    barcode           VARCHAR(60),
    option1           VARCHAR(100),
    option2           VARCHAR(100),
    price             DECIMAL(15,2) NOT NULL,
    compare_at_price  DECIMAL(15,2),
    cost_price        DECIMAL(15,2),
    stock_quantity    INT           NOT NULL DEFAULT 0,
    weight_gram       INT           NOT NULL DEFAULT 500,
    image_url         VARCHAR(500),
    is_default        BOOLEAN       NOT NULL DEFAULT FALSE,
    active            BOOLEAN       NOT NULL DEFAULT TRUE,
    sort_order        INT           NOT NULL DEFAULT 0,
    version           INT           NOT NULL DEFAULT 0,
    created_at        DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at        DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_var_product FOREIGN KEY (product_id) REFERENCES products(id),
    CONSTRAINT chk_var_price  CHECK (price >= 0),
    CONSTRAINT chk_var_stock  CHECK (stock_quantity >= 0)
) ENGINE=InnoDB;

CREATE TABLE product_images (
    id          BIGINT       NOT NULL AUTO_INCREMENT PRIMARY KEY,
    product_id  BIGINT       NOT NULL,
    url         VARCHAR(500) NOT NULL,
    alt         VARCHAR(200),
    sort_order  INT          NOT NULL DEFAULT 0,
    CONSTRAINT fk_img_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- Thong so mo rong dang key-value (so manh ghep, so nguoi choi, tan so dieu khien...)
CREATE TABLE product_specs (
    id          BIGINT       NOT NULL AUTO_INCREMENT PRIMARY KEY,
    product_id  BIGINT       NOT NULL,
    spec_key    VARCHAR(100) NOT NULL,
    spec_value  VARCHAR(255) NOT NULL,
    sort_order  INT          NOT NULL DEFAULT 0,
    CONSTRAINT fk_spec_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- =====================================================================
-- 4. YEU THICH & GIO HANG
-- =====================================================================
CREATE TABLE wishlist_items (
    id          BIGINT   NOT NULL AUTO_INCREMENT PRIMARY KEY,
    user_id     BIGINT   NOT NULL,
    product_id  BIGINT   NOT NULL,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_wish UNIQUE (user_id, product_id),
    CONSTRAINT fk_wish_user    FOREIGN KEY (user_id)    REFERENCES users(id)    ON DELETE CASCADE,
    CONSTRAINT fk_wish_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE cart_items (
    id          BIGINT   NOT NULL AUTO_INCREMENT PRIMARY KEY,
    user_id     BIGINT   NOT NULL,
    variant_id  BIGINT   NOT NULL,
    quantity    INT      NOT NULL,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_cart UNIQUE (user_id, variant_id),
    CONSTRAINT fk_cart_user    FOREIGN KEY (user_id)    REFERENCES users(id)            ON DELETE CASCADE,
    CONSTRAINT fk_cart_variant FOREIGN KEY (variant_id) REFERENCES product_variants(id) ON DELETE CASCADE,
    CONSTRAINT chk_cart_qty CHECK (quantity > 0)
) ENGINE=InnoDB;

-- =====================================================================
-- 5. KHUYEN MAI
-- =====================================================================
CREATE TABLE vouchers (
    id               BIGINT        NOT NULL AUTO_INCREMENT PRIMARY KEY,
    code             VARCHAR(30)   NOT NULL UNIQUE,
    name             VARCHAR(150)  NOT NULL,
    description      VARCHAR(500),
    type             VARCHAR(20)   NOT NULL,
    value            DECIMAL(15,2) NOT NULL DEFAULT 0,
    max_discount     DECIMAL(15,2),
    min_order_value  DECIMAL(15,2) NOT NULL DEFAULT 0,
    start_at         DATETIME      NOT NULL,
    end_at           DATETIME      NOT NULL,
    usage_limit      INT,
    used_count       INT           NOT NULL DEFAULT 0,
    per_user_limit   INT           NOT NULL DEFAULT 1,
    active           BOOLEAN       NOT NULL DEFAULT TRUE,
    created_at       DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at       DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_voucher_type CHECK (type IN ('PERCENT','FIXED','FREESHIP'))
) ENGINE=InnoDB;

-- Chuong trinh giam gia theo thoi gian (vd: Sale Trung thu -20% danh muc Board game)
CREATE TABLE campaigns (
    id                BIGINT       NOT NULL AUTO_INCREMENT PRIMARY KEY,
    name              VARCHAR(150) NOT NULL,
    description       VARCHAR(500),
    discount_percent  INT          NOT NULL,
    scope_type        VARCHAR(20)  NOT NULL DEFAULT 'ALL',
    scope_id          BIGINT       NULL,
    badge_label       VARCHAR(50),
    start_at          DATETIME     NOT NULL,
    end_at            DATETIME     NOT NULL,
    active            BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at        DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at        DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_camp_scope   CHECK (scope_type IN ('ALL','CATEGORY','BRAND','FRANCHISE','PRODUCT')),
    CONSTRAINT chk_camp_percent CHECK (discount_percent BETWEEN 1 AND 90)
) ENGINE=InnoDB;

CREATE TABLE banners (
    id           BIGINT       NOT NULL AUTO_INCREMENT PRIMARY KEY,
    title        VARCHAR(150) NOT NULL,
    subtitle     VARCHAR(300),
    image_url    VARCHAR(500),
    link_url     VARCHAR(300),
    button_text  VARCHAR(50),
    bg_color     VARCHAR(20),
    sort_order   INT          NOT NULL DEFAULT 0,
    active       BOOLEAN      NOT NULL DEFAULT TRUE,
    start_at     DATETIME     NULL,
    end_at       DATETIME     NULL,
    created_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

-- =====================================================================
-- 6. DON HANG - THANH TOAN - DOI TRA
-- =====================================================================
CREATE TABLE orders (
    id               BIGINT        NOT NULL AUTO_INCREMENT PRIMARY KEY,
    order_code       VARCHAR(30)   NOT NULL UNIQUE,
    user_id          BIGINT        NOT NULL,
    receiver_name    VARCHAR(100)  NOT NULL,
    phone            VARCHAR(20)   NOT NULL,
    province_name    VARCHAR(100)  NOT NULL,
    district_name    VARCHAR(100)  NOT NULL,
    ward_name        VARCHAR(100)  NOT NULL,
    address_detail   VARCHAR(255)  NOT NULL,
    district_id      INT,
    ward_code        VARCHAR(20),
    note             VARCHAR(500),
    gift_wrap        BOOLEAN       NOT NULL DEFAULT FALSE,
    gift_message     VARCHAR(300),
    subtotal         DECIMAL(15,2) NOT NULL,
    discount_amount  DECIMAL(15,2) NOT NULL DEFAULT 0,
    shipping_fee     DECIMAL(15,2) NOT NULL DEFAULT 0,
    shipping_discount DECIMAL(15,2) NOT NULL DEFAULT 0,
    gift_wrap_fee    DECIMAL(15,2) NOT NULL DEFAULT 0,
    total_amount     DECIMAL(15,2) NOT NULL,
    voucher_id       BIGINT        NULL,
    voucher_code     VARCHAR(30),
    points_used      INT           NOT NULL DEFAULT 0,   -- so diem khach dung de tru tien
    points_discount  DECIMAL(15,2) NOT NULL DEFAULT 0,   -- so tien duoc tru tu diem
    points_earned    INT           NOT NULL DEFAULT 0,   -- diem cong khi don HOAN TAT
    status           VARCHAR(30)   NOT NULL,
    payment_method   VARCHAR(20)   NOT NULL,
    payment_status   VARCHAR(20)   NOT NULL DEFAULT 'UNPAID',
    paid_at          DATETIME      NULL,
    payment_deadline DATETIME      NULL,
    cancel_reason    VARCHAR(300),
    internal_note    VARCHAR(500),
    delivered_at     DATETIME      NULL,
    created_at       DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at       DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_ord_user    FOREIGN KEY (user_id)    REFERENCES users(id),
    CONSTRAINT fk_ord_voucher FOREIGN KEY (voucher_id) REFERENCES vouchers(id) ON DELETE SET NULL,
    CONSTRAINT chk_ord_status CHECK (status IN ('PENDING_PAYMENT','PENDING','CONFIRMED','PACKING','SHIPPING',
        'DELIVERED','DELIVERY_FAILED','COMPLETED','CANCELLED','RETURN_REQUESTED','RETURNED')),
    CONSTRAINT chk_ord_pm     CHECK (payment_method IN ('COD','MOMO')),
    CONSTRAINT chk_ord_ps     CHECK (payment_status IN ('UNPAID','PAID','FAILED','REFUND_PENDING','REFUNDED'))
) ENGINE=InnoDB;

CREATE INDEX idx_ord_status  ON orders(status);
CREATE INDEX idx_ord_created ON orders(created_at);

CREATE TABLE order_items (
    id              BIGINT        NOT NULL AUTO_INCREMENT PRIMARY KEY,
    order_id        BIGINT        NOT NULL,
    product_id      BIGINT        NULL,
    variant_id      BIGINT        NULL,
    product_name    VARCHAR(200)  NOT NULL,
    variant_name    VARCHAR(200),
    sku             VARCHAR(60)   NOT NULL,
    image_url       VARCHAR(500),
    unit_price      DECIMAL(15,2) NOT NULL,
    original_price  DECIMAL(15,2),
    cost_price      DECIMAL(15,2) NULL,                  -- gia von tai thoi diem ban (bao cao loi nhuan)
    quantity        INT           NOT NULL,
    reviewed        BOOLEAN       NOT NULL DEFAULT FALSE,
    CONSTRAINT fk_oi_order   FOREIGN KEY (order_id)   REFERENCES orders(id)           ON DELETE CASCADE,
    CONSTRAINT fk_oi_product FOREIGN KEY (product_id) REFERENCES products(id)         ON DELETE SET NULL,
    CONSTRAINT fk_oi_variant FOREIGN KEY (variant_id) REFERENCES product_variants(id) ON DELETE SET NULL,
    CONSTRAINT chk_oi_qty CHECK (quantity > 0)
) ENGINE=InnoDB;

CREATE TABLE order_status_history (
    id           BIGINT       NOT NULL AUTO_INCREMENT PRIMARY KEY,
    order_id     BIGINT       NOT NULL,
    from_status  VARCHAR(30),
    to_status    VARCHAR(30)  NOT NULL,
    note         VARCHAR(500),
    changed_by   VARCHAR(50),
    created_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_osh_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE voucher_usages (
    id               BIGINT        NOT NULL AUTO_INCREMENT PRIMARY KEY,
    voucher_id       BIGINT        NOT NULL,
    user_id          BIGINT        NOT NULL,
    order_id         BIGINT        NOT NULL,
    discount_amount  DECIMAL(15,2) NOT NULL,
    created_at       DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_vu_voucher FOREIGN KEY (voucher_id) REFERENCES vouchers(id) ON DELETE CASCADE,
    CONSTRAINT fk_vu_user    FOREIGN KEY (user_id)    REFERENCES users(id)    ON DELETE CASCADE,
    CONSTRAINT fk_vu_order   FOREIGN KEY (order_id)   REFERENCES orders(id)   ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE payment_transactions (
    id              BIGINT        NOT NULL AUTO_INCREMENT PRIMARY KEY,
    order_id        BIGINT        NOT NULL,
    provider        VARCHAR(20)   NOT NULL DEFAULT 'MOMO',    -- MOMO | COD | CASH | BANK_TRANSFER
    txn_ref         VARCHAR(50)   NOT NULL UNIQUE,
    amount          DECIMAL(15,2) NOT NULL,
    bank_code       VARCHAR(30),
    transaction_no  VARCHAR(50),
    response_code   VARCHAR(10),
    status          VARCHAR(20)   NOT NULL DEFAULT 'PENDING',
    -- PAYMENT = khach tra tien, REFUND = shop hoan tien (so cai thu - chi de doi soat)
    kind            VARCHAR(10)   NOT NULL DEFAULT 'PAYMENT',
    note            VARCHAR(300),
    created_by      VARCHAR(50),
    raw_data        TEXT,
    created_at      DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_pt_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE,
    CONSTRAINT chk_pt_kind CHECK (kind IN ('PAYMENT','REFUND')),
    INDEX idx_pt_created (created_at)
) ENGINE=InnoDB;

CREATE TABLE return_requests (
    id             BIGINT        NOT NULL AUTO_INCREMENT PRIMARY KEY,
    order_id       BIGINT        NOT NULL UNIQUE,
    user_id        BIGINT        NOT NULL,
    reason         VARCHAR(200)  NOT NULL,
    description    VARCHAR(1000),
    image_urls     TEXT,
    status         VARCHAR(20)   NOT NULL DEFAULT 'REQUESTED',
    admin_note     VARCHAR(500),
    refund_amount  DECIMAL(15,2),
    processed_by   VARCHAR(50),
    processed_at   DATETIME      NULL,
    created_at     DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at     DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_rr_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE,
    CONSTRAINT fk_rr_user  FOREIGN KEY (user_id)  REFERENCES users(id),
    CONSTRAINT chk_rr_status CHECK (status IN ('REQUESTED','APPROVED','REJECTED'))
) ENGINE=InnoDB;

-- =====================================================================
-- 7. DANH GIA
-- =====================================================================
CREATE TABLE reviews (
    id             BIGINT    NOT NULL AUTO_INCREMENT PRIMARY KEY,
    product_id     BIGINT    NOT NULL,
    user_id        BIGINT    NOT NULL,
    order_item_id  BIGINT    NULL,
    variant_name   VARCHAR(200),
    rating         INT       NOT NULL,
    comment        TEXT,
    image_urls     TEXT,
    hidden         BOOLEAN   NOT NULL DEFAULT FALSE,
    flagged        BOOLEAN   NOT NULL DEFAULT FALSE,   -- chua tu khoa cam -> an, cho duyet
    flag_reason    VARCHAR(300),
    admin_reply    TEXT,
    replied_at     DATETIME  NULL,
    created_at     DATETIME  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at     DATETIME  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_review_item UNIQUE (order_item_id),
    CONSTRAINT fk_rev_product FOREIGN KEY (product_id)    REFERENCES products(id) ON DELETE CASCADE,
    CONSTRAINT fk_rev_user    FOREIGN KEY (user_id)       REFERENCES users(id)    ON DELETE CASCADE,
    CONSTRAINT fk_rev_oi      FOREIGN KEY (order_item_id) REFERENCES order_items(id) ON DELETE SET NULL,
    CONSTRAINT chk_rev_rating CHECK (rating BETWEEN 1 AND 5)
) ENGINE=InnoDB;

CREATE TABLE banned_keywords (
    id          BIGINT       NOT NULL AUTO_INCREMENT PRIMARY KEY,
    keyword     VARCHAR(100) NOT NULL UNIQUE,   -- luu dang khong dau, chu thuong
    created_by  VARCHAR(50),
    created_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

-- =====================================================================
-- 8. KHO HANG
-- =====================================================================
CREATE TABLE suppliers (
    id              BIGINT        NOT NULL AUTO_INCREMENT PRIMARY KEY,
    code            VARCHAR(30)   NOT NULL UNIQUE,
    name            VARCHAR(200)  NOT NULL,
    contact_name    VARCHAR(100),
    phone           VARCHAR(20),
    email           VARCHAR(100),
    address         VARCHAR(300),
    tax_code        VARCHAR(20),
    note            VARCHAR(500),
    active          BOOLEAN       NOT NULL DEFAULT TRUE,
    created_at      DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE stock_receipts (
    id              BIGINT        NOT NULL AUTO_INCREMENT PRIMARY KEY,
    code            VARCHAR(30)   NOT NULL UNIQUE,
    supplier_id     BIGINT        NULL,
    supplier        VARCHAR(200),                        -- ten NCC luu kem (giu lai khi NCC bi xoa/doi ten)
    note            VARCHAR(500),
    total_quantity  INT           NOT NULL DEFAULT 0,
    total_cost      DECIMAL(15,2) NOT NULL DEFAULT 0,
    created_by      VARCHAR(50),
    created_at      DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_sr_supplier FOREIGN KEY (supplier_id) REFERENCES suppliers(id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE stock_receipt_items (
    id            BIGINT        NOT NULL AUTO_INCREMENT PRIMARY KEY,
    receipt_id    BIGINT        NOT NULL,
    variant_id    BIGINT        NULL,
    sku           VARCHAR(60)   NOT NULL,
    product_name  VARCHAR(300)  NOT NULL,
    quantity      INT           NOT NULL,
    unit_cost     DECIMAL(15,2) NOT NULL DEFAULT 0,
    CONSTRAINT fk_sri_receipt FOREIGN KEY (receipt_id) REFERENCES stock_receipts(id) ON DELETE CASCADE,
    CONSTRAINT fk_sri_variant FOREIGN KEY (variant_id) REFERENCES product_variants(id) ON DELETE SET NULL,
    CONSTRAINT chk_sri_qty CHECK (quantity > 0)
) ENGINE=InnoDB;

-- Nhat ky bien dong ton kho: moi lan nhap / ban / huy / tra / dieu chinh deu ghi lai
CREATE TABLE stock_movements (
    id               BIGINT       NOT NULL AUTO_INCREMENT PRIMARY KEY,
    variant_id       BIGINT       NULL,
    sku              VARCHAR(60)  NOT NULL,
    type             VARCHAR(20)  NOT NULL,
    quantity_change  INT          NOT NULL,
    balance_after    INT          NOT NULL,
    ref_code         VARCHAR(50),
    note             VARCHAR(300),
    created_by       VARCHAR(50),
    created_at       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_sm_variant FOREIGN KEY (variant_id) REFERENCES product_variants(id) ON DELETE SET NULL,
    CONSTRAINT chk_sm_type CHECK (type IN ('INITIAL','IMPORT','SALE','CANCEL','RETURN','ADJUSTMENT'))
) ENGINE=InnoDB;

CREATE INDEX idx_sm_variant ON stock_movements(variant_id, created_at);

-- =====================================================================
-- 9. KHACH HANG THAN THIET - THONG BAO - NHAT KY
-- =====================================================================
CREATE TABLE point_transactions (
    id             BIGINT       NOT NULL AUTO_INCREMENT PRIMARY KEY,
    user_id        BIGINT       NOT NULL,
    order_id       BIGINT       NULL,
    type           VARCHAR(20)  NOT NULL,     -- EARN / REDEEM / REFUND / ADJUST
    points         INT          NOT NULL,     -- + cong, - tru
    balance_after  INT          NOT NULL,
    note           VARCHAR(300),
    created_by     VARCHAR(50),
    created_at     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_ptx_user  FOREIGN KEY (user_id)  REFERENCES users(id)  ON DELETE CASCADE,
    CONSTRAINT fk_ptx_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE SET NULL,
    CONSTRAINT chk_ptx_type CHECK (type IN ('EARN','REDEEM','REFUND','ADJUST'))
) ENGINE=InnoDB;
CREATE INDEX idx_pt_user ON point_transactions(user_id, id);

-- Thong bao trong ung dung (chuong thong bao) - moi nguoi nhan 1 dong, day realtime qua WebSocket
CREATE TABLE notifications (
    id          BIGINT       NOT NULL AUTO_INCREMENT PRIMARY KEY,
    user_id     BIGINT       NOT NULL,
    type        VARCHAR(30)  NOT NULL,
    title       VARCHAR(200) NOT NULL,
    message     VARCHAR(500),
    link        VARCHAR(300),
    is_read     BOOLEAN      NOT NULL DEFAULT FALSE,
    created_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_noti_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;
CREATE INDEX idx_noti_user ON notifications(user_id, is_read, id);

-- Nhat ky thao tac cua nhan vien / quan tri (truy vet)
CREATE TABLE audit_logs (
    id           BIGINT       NOT NULL AUTO_INCREMENT PRIMARY KEY,
    actor        VARCHAR(50)  NOT NULL,
    actor_role   VARCHAR(20),
    action       VARCHAR(30)  NOT NULL,     -- CREATE / UPDATE / DELETE / STATUS / ADJUST / LOGIN ...
    entity_type  VARCHAR(40)  NOT NULL,     -- PRODUCT / ORDER / VOUCHER / USER ...
    entity_id    VARCHAR(40),
    summary      VARCHAR(500) NOT NULL,
    ip           VARCHAR(45),
    created_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
CREATE INDEX idx_audit_time ON audit_logs(created_at);
CREATE INDEX idx_audit_entity ON audit_logs(entity_type, entity_id);

