UPDATE reviews SET admin_reply = 'ToyLand cảm ơn bạn đã tin tưởng ủng hộ! 💛', replied_at = created_at WHERE rating >= 5 AND id % 3 = 0;

UPDATE order_items oi JOIN reviews r ON r.order_item_id = oi.id SET oi.reviewed = TRUE;

UPDATE order_items oi JOIN orders o ON o.id = oi.order_id LEFT JOIN reviews r ON r.order_item_id = oi.id SET oi.reviewed = FALSE WHERE r.id IS NULL;








